function isDown(...codes){return codes.some(c=>keys[c])}
function rect(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function update(){frame++;if(state!=='playing')return;levelTime+=1/60;if(mode!==4)time=Math.max(0,time-1/60);if(time===0){state='over';beep(150,.3,'sawtooth');return}if(invincible>0)invincible--;
