player.vy=Math.min(player.vy+.48,10);player.x=Math.max(0,player.x+player.vx);const oldY=player.y;player.y+=player.vy;player.ground=false;
for(const p of platforms){if(p.type==='gap')continue;if(player.x+player.w>p.x&&player.x<p.x+p.w&&oldY+player.h<=p.y+4&&player.y+player.h>=p.y&&player.vy>=0){player.y=p.y-player.h;player.vy=0;player.ground=true}}
const gap=platforms.find(p=>p.type==='gap'&&player.x+player.w>p.x&&player.x<p.x+p.w);if(gap&&player.y+player.h>=390){player.ground=false}
if(player.y>H+30){loseLife()}
for(const p of platforms){if(p.type==='brick'&&player.vy<0&&player.x+player.w>p.x&&player.x<p.x+p.w&&oldY<p.y+p.h&&player.y>=p.y+p.h){player.y=p.y+p.h;player.vy=1;score+=10;beep(180,.05)}}
player.walk+=Math.abs(player.vx)*.15;
for(const o of objects){if(o.dead)continue;if(o.type==='enemy'){o.x+=o.vx;if(o.x<80||o.x>2200+level*320)o.vx*=-1;if(hit(player,o)){if(player.vy>1&&oldY+player.h<=o.y+7){o.dead=true;player.vy=-7;score+=200;beep(250,.12)}else if(invincible===0)loseLife();}}
