if(boss){boss.x+=boss.vx;if(boss.x<970||boss.x>1450)boss.vx*=-1;if(boss.hit>0)boss.hit--;if(hit(player,boss)){if(player.vy>1&&oldY+player.h<=boss.y+12&&boss.hit===0){boss.hp--;boss.hit=55;player.vy=-8;score+=500;beep(190,.16,'sawtooth');if(boss.hp<=0){score+=2000;finishLevel()}}else if(invincible===0)loseLife()}}
cam=Math.max(0,Math.min(player.x-230,2600- W));if(state==='playing'&&mode===1&&coins>=30)finishLevel();prevKeys={...keys};}
function hit(a,b){return a.x+a.w>b.x&&a.x<b.x+b.w&&a.y+a.h>b.y&&a.y<b.y+b.h}
function loseLife(){if(mode===4){player.x=Math.max(35,player.x-90);player.y=280;player.vy=0;invincible=100;return}lives--;beep(120,.23,'sawtooth');if(lives<=0){state='over';return}player.x=Math.max(35,player.x-150);player.y=260;player.vy=0;invincible=100}
function finishLevel(){if(levelComplete)return;levelComplete=true;score+=Math.max(0,Math.floor(time))*10+coins*25;saved.best=Math.max(saved.best,score);if(mode===0){const progress=world*3+level+1;saved.unlocked=Math.max(saved.unlocked,progress);saved.world=Math.min(2,Math.floor(progress/3));saved.level=progress%3;if(level<2)level++;else if(world<2){world++;level=0}else{state='clear';save();return}}state='clear';beep(740,.2,'triangle');save()}
