// distant layered hills and pixel clouds
for(let i=0;i<8;i++){const x=((i*190-(cam*.22)%1520)+1520)%1520-40;ctx.fillStyle=theme.hill;ctx.beginPath();ctx.moveTo(x,355);ctx.lineTo(x+95,225+(i%3)*24);ctx.lineTo(x+190,355);ctx.fill();}
for(let i=0;i<6;i++){let x=((i*175-(cam*.12)%1050)+1050)%1050-30,y=60+(i%3)*47;rect(ctx,x,y,46,12,'#ffffffaa');rect(ctx,x+12,y-8,28,12,'#ffffffaa');rect(ctx,x+43,y+4,20,8,'#ffffffaa')}
