function drawWorld(){drawBackground();ctx.save();ctx.translate(-cam,0);
// terrain
for(const p of platforms){if(p.type==='gap')continue;if(p.type==='ground'){rect(ctx,p.x,p.y,p.w,p.h,world===2?'#d7e9ef':world===1?'#c79343':'#96512e');rect(ctx,p.x,p.y,p.w,12,worlds[world].ground);for(let bx=p.x;bx<p.x+p.w;bx+=32){rect(ctx,bx,p.y+18,14,5,world===2?'#bad5df':world===1?'#b87e37':'#814327');rect(ctx,bx+16,p.y+45,12,5,'#00000012')}}else{rect(ctx,p.x,p.y,p.w,p.h,'#c6753f');rect(ctx,p.x,p.y,p.w,5,'#f4b65d');for(let bx=p.x;bx<p.x+p.w;bx+=24)rect(ctx,bx,p.y+8,2,p.h-8,'#8e4a32')}}
