for(const o of objects){if(o.dead)continue;if(o.type==='pipe'){rect(ctx,o.x,o.y,o.w,o.h,'#249458');rect(ctx,o.x-5,o.y,o.w+10,10,'#49c875');rect(ctx,o.x+8,o.y+12,7,o.h-12,'#56d78b')}
