if(o.type==='enemy'){rect(ctx,o.x+3,o.y+8,22,17,'#9b5539');rect(ctx,o.x,o.y+16,28,10,'#704333');rect(ctx,o.x+6,o.y+12,5,6,'#fff');rect(ctx,o.x+18,o.y+12,5,6,'#fff');rect(ctx,o.x+8,o.y+14,2,4,'#252b3a');rect(ctx,o.x+20,o.y+14,2,4,'#252b3a')}
